class HomeScreen extends ConsumerWidget{const HomeScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final repo=ref.watch(mockRepositoryProvider);final services=repo.services().take(6).toList();return Scaffold(appBar:AppBar(title:const Text('Good morning, Shammah'),actions:[IconButton(onPressed:()=>showComingSoon(context,'Notifications'),icon:const Icon(Icons.notifications_none),tooltip:'Notifications')]),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Harare, Zimbabwe'),const SizedBox(height:12),TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search Zaylo services')),SectionHeader('Quick actions',action:TextButton(onPressed:()=>context.go('/explore'),child:const Text('All Services'))),GridView.count(crossAxisCount:3,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),children:[for(final s in services) ZayloCard(onTap:()=>context.push(s.route),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(IconData(s.icon,fontFamily:'MaterialIcons')),const SizedBox(height:8),Text(s.name,textAlign:TextAlign.center)]))]),const SectionHeader('Important local alerts'),const ZayloCard(child:Text(AppConstants.mockNotice)),SectionHeader('Upcoming bill reminders',action:TextButton(onPressed:()=>context.push('/reminders'),child:const Text('See all'))),...repo.bills().map((b)=>ListTile(title:Text(b.name),subtitle:Text('${b.frequency} • due ${b.dueDate.day}/${b.dueDate.month}'),trailing:Text('\$${b.amount.toStringAsFixed(0)}'))),SectionHeader('Recent expense summary',action:TextButton(onPressed:()=>context.push('/expenses'),child:const Text('See all'))),const ZayloCard(child:Text('Spent \$50 this week. Remaining budget: \$230.')),SectionHeader('Trending jobs and prices',action:TextButton(onPressed:()=>context.push('/jobs'),child:const Text('See all'))),...repo.jobs().take(2).map((j)=>ListTile(title:Text(j.title),subtitle:Text('${j.company} • ${j.location}')))]));}}
